entries[99652] = { ["name"] = "Gehirnsplitter", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nEchtgold (8), Infernorubin (2), Gehärteter Elementiumbarren (3), Chaoskugel (5)\nGehirnsplitter\nWird beim Anlegen gebunden\nEinhändig Dolch\n1,231 - 2,288 Schaden Tempo 1.80\n(977.50 Schaden pro Sekunde)\n+155 Beweglichkeit\n+232 Ausdauer\nErhöht Eure Trefferwertung um + 103.\nErhöht Eure Tempowertung um + 103.\nHaltbarkeit 75 / 75\n85" }
entries[99653] = { ["name"] = "Meisterhafte Elementiumzauberklinge", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nEchtgold (8), Ozeansaphir , Jaspis (2), Gehärteter Elementiumbarren , Chaoskugel (5)\nMeisterhafte Elementiumzauberklinge\nWird beim Anlegen gebunden\nEinhändig Dolch\n615 - 1,144 Schaden Tempo 1.80\n(488.61 Schaden pro Sekunde)\n+232 Ausdauer\n+155 Intelligenz\nErhöht Eure Trefferwertung um + 103.\nErhöht Eure kritische Trefferwertung um + 103.\nErhöht die Zaubermacht um + 2.066.\nHaltbarkeit 80 / 80\n85" }
entries[99654] = { ["name"] = "Lichtgeschmiedeter Elementiumhammer", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nEchtgold (8), Flüchtiges Wasser (30), Chaoskugel (5)\nLichtgeschmiedeter Elementiumhammer\nWird beim Anlegen gebunden\nEinhändig Streitkolben\n650 - 1,208 Schaden Tempo 1.90\n(488.95 Schaden pro Sekunde)\n+232 Ausdauer\n+155 Intelligenz\n+103 Willenskraft\nErhöht die Zaubermacht um + 2.066.\nErhöht Eure Meisterschaftswertung um + 103.\nHaltbarkeit 110 / 110\n85" }
