entries[99656] = { ["name"] = "Pyriumzauberschutz", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nEchtgold (8), Gluttopas , Gehärteter Elementiumbarren (3), Chaoskugel (5)\nPyriumzauberschutz\nWird beim Anlegen gebunden\nEinhändig Schwert\n1,779 - 3,305 Schaden Tempo 2.60\n(977.69 Schaden pro Sekunde)\n+155 Beweglichkeit\n+232 Ausdauer\nErhöht Eure Trefferwertung um + 103.\nErhöht Eure Meisterschaftswertung um + 103.\nHaltbarkeit 105 / 105\n85\n\"Die beste Verteidigung gegen Zauberwirker ist es, sie umzubringen.\"" }
